from abc import ABC, abstractmethod
import requests
from bs4 import BeautifulSoup

class BaseCrawler(ABC):
    def __init__(self, base_url):
        self.base_url = base_url

    @abstractmethod
    def discover_documents(self):
        pass

    def _get_page(self, url):
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        return BeautifulSoup(response.text, 'html.parser')


# ai_orchestrator/source_seeding/discovery/parliament_crawler.py
from .base_crawler import BaseCrawler

class ParliamentCrawler(BaseCrawler):
    def __init__(self):
        super().__init__('https://parliament.gh')

    def discover_documents(self):
        soup = self._get_page(f"{self.base_url}/api/bills")
        documents = []
        for item in soup.select('.bill-item'):
            doc_url = item.find('a')['href']
            documents.append({
                'url': f"{self.base_url}{doc_url}",
                'source': 'parliament',
                'file_type': 'pdf' if doc_url.endswith('.pdf') else 'html'
            })
        return documents


