from abc import ABC, abstractmethod
import re

class BaseMetadataParser(ABC):
    @abstractmethod
    def parse(self, content):
        pass

    def _extract_date(self, text):
        match = re.search(r'\b\d{4}-\d{2}-\d{2}\b', text)
        return match.group(0) if match else None


# ai_orchestrator/source_seeding/metadata/parliament_parser.py
from .base_parser import BaseMetadataParser

class ParliamentMetadataParser(BaseMetadataParser):
    def parse(self, content):
        if isinstance(content, bytes):  # PDF content
            text = content.decode('utf-8', errors='ignore')
        else:  # HTML content
            text = content

        title = self._extract_title(text)
        date = self._extract_date(text)
        
        return {
            'title': title,
            'date_published': date,
            'document_type': 'bill',
            'jurisdiction': 'ghana',
            'source': 'parliament'
        }

    def _extract_title(self, text):
        match = re.search(r'<title>(.*?)</title>', text)
        return match.group(1).strip() if match else 'Untitled'


# ai_orchestrator/source_seeding/storage/database.py
from sqlalchemy import create_engine, Column, String, JSON, DateTime
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker
import uuid
from datetime import datetime

Base = declarative_base()

class LegalDocument(Base):
    __tablename__ = 'legal_documents'
    
    id = Column(String, primary_key=True, default=lambda: str(uuid.uuid4()))
    source = Column(String, nullable=False)
    metadata = Column(JSON, nullable=False)
    file_path = Column(String, nullable=False)
    created_at = Column(DateTime, default=datetime.utcnow)


# ai_orchestrator/source_seeding/tasks/celery_tasks.py
from celery import Celery
from .discovery.parliament_crawler import ParliamentCrawler
from .metadata.parliament_parser import ParliamentMetadataParser
from .storage.database import LegalDocument, Base
from sqlalchemy import create_engine
import os

celery = Celery('tasks', broker=os.getenv('CELERY_BROKER_URL'))

@celery.task
def seed_parliament():
    engine = create_engine(os.getenv('DATABASE_URL'))
    Base.metadata.create_all(engine)
    Session = sessionmaker(bind=engine)
    
    crawler = ParliamentCrawler()
    documents = crawler.discover_documents()
    
    session = Session()
    for doc in documents:
        response = requests.get(doc['url'])
        parser = ParliamentMetadataParser()
        metadata = parser.parse(response.content)
        
        db_doc = LegalDocument(
            source=doc['source'],
            metadata=metadata,
            file_path=f"parliament_docs/{metadata['title']}.pdf"
        )
        session.add(db_doc)
    session.commit()


