# ai_orchestrator/tests/test_metadata.py
import pytest
from ai_orchestrator.source_seeding.metadata.parliament_parser import ParliamentMetadataParser

def test_parliament_parser_html():
    html_content = '''
    <html>
        <head><title>Sample Bill Title</title></head>
        <body>Passed on 2023-04-05</body>
    </html>
    '''
    parser = ParliamentMetadataParser()
    metadata = parser.parse(html_content)
    
    assert metadata['title'] == 'Sample Bill Title'
    assert metadata['date_published'] == '2023-04-05'
    assert metadata['document_type'] == 'bill'

def test_parliament_parser_pdf():
    pdf_content = b'%PDF-1.4\nSample text with date 2023-04-05'
    parser = ParliamentMetadataParser()
    metadata = parser.parse(pdf_content)
    
    assert metadata['date_published'] == '2023-04-05'


# ai_orchestrator/tests/test_storage.py
import pytest
from sqlalchemy import create_engine, text
from ai_orchestrator.source_seeding.storage.database import LegalDocument, Base

def test_database_storage():
    engine = create_engine('sqlite:///:memory:')
    Base.metadata.create_all(engine)
    
    with engine.connect() as conn:
        doc = LegalDocument(
            source='parliament',
            metadata={'title': 'Test Bill', 'date_published': '2023-04-05'},
            file_path='test_path.pdf'
        )
        doc.id = 'test-uuid'  # Bypass UUID generation for test
        doc.created_at = None  # Let default handle it
        
        conn.execute(text("INSERT INTO legal_documents (id, source, metadata, file_path) VALUES (:id, :source, :metadata, :file_path)"),
                    {'id': doc.id, 'source': doc.source, 'metadata': doc.metadata, 'file_path': doc.file_path})
        
        result = conn.execute(text("SELECT * FROM legal_documents WHERE id = 'test-uuid'")).first()
        assert result.metadata['title'] == 'Test Bill'
        assert result.file_path == 'test_path.pdf'